    const parsePanelResponse = async (resp) => {
      const text = await resp.text();
      if (ensureParseWorker()) {
        try {
          const r = await workerParse(text);
          if (r && r.ok === true) return r.data;
        } catch {
          // worker 会话异常 → 走主线程解析兜底
        }
      }
      try {
        return JSON.parse(text);
      } catch {
        return null;
      }
    };

